from flask import Flask, g, request
import logging

app = Flask(__name__)
app.logger.setLevel(logging.INFO)

@app.before_request
def add_request_context():
    g.request_path = request.path

@app.after_request
def add_header(response):
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response
